const { useState, useEffect } = React;

const URL = '/api/courses';

function CourseList() {
  const [courses, setCourses] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch(URL)
      .then((res) => {
        if (!res.ok) throw new Error('불러오지 못했습니다 (' + res.status + ')');
        return res.json();
      })
      .then((list) => setCourses(list))
      .catch((e) => setError(e));
  }, []);

  if (error !== null) {
    return (
      <div>
        <p className="state">불러오지 못했습니다</p>
        <p className="hint">잠시 뒤 다시 시도해 주세요</p>
      </div>
    );
  }

  if (courses === null) {
    return <p className="state">불러오는 중…</p>;
  }

  if (courses.length === 0) {
    return (
      <div>
        <p className="state">등록된 코스가 없습니다</p>
        <p className="hint">새 코스를 추가해 보세요</p>
      </div>
    );
  }

  return (
    <div>
      <p className="state">코스 {courses.length}개</p>
      {courses.map((c) => <p className="course" key={c.id}>{c.name}</p>)}
    </div>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<CourseList />);

